begin;
set local search_path='';
set local lock_timeout='3s';
do $completion_lock$
declare item record; total integer:=0;
begin
 if not pg_try_advisory_xact_lock(hashtextextended('mam:directory-role-control',0)) then raise exception 'Completion role control busy.' using errcode='55P03'; end if;
 for item in select n.nspname,c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private') and c.relkind in('r','p') order by n.nspname,c.relname loop
  total:=total+1; if total>256 then raise exception 'Unbounded completion relation set.' using errcode='55000'; end if;
  execute format('lock table %I.%I in share row exclusive mode nowait',item.nspname,item.relname);
 end loop;
end $completion_lock$;
do $completion_predecessor$
begin
 if current_setting('server_version_num')::integer/10000 not in (16,17) or (select count(*) from private.confirmed_test_purge_schema)<>1 or private.confirmed_test_purge_schema_hash() is distinct from (select schema_hash from private.confirmed_test_purge_schema where singleton) then raise exception 'Completion requires the exact captured predecessor catalog.' using errcode='55000'; end if;
end $completion_predecessor$;
create function pg_temp.performance_release_security() returns jsonb language sql stable set search_path='' as $performance_security$
with feature_base as (select c.oid,c.reltoastrelid from pg_class c where c.oid in(select to_regclass(name) from unnest(array['private.performance_reviews','private.performance_review_events','private.performance_review_operations','private.performance_review_mail_outbox','private.performance_reviews_review_no_seq','private.performance_review_events_id_seq']::text[]) name)), feature_relations as (
select oid from feature_base union select reltoastrelid from feature_base where reltoastrelid<>0 union select indexrelid from pg_index where indrelid in(select oid from feature_base union select reltoastrelid from feature_base)
), feature_types as (select t.oid from pg_type t where t.typrelid in(select oid from feature_relations) or t.typelem in(select c.reltype from pg_class c where c.oid in(select oid from feature_relations) and c.reltype<>0))
select jsonb_build_object(
  'schemas',(select jsonb_agg(to_jsonb(n) order by n.oid) from pg_namespace n where n.nspname !~ '^pg_temp_' and n.nspname !~ '^pg_toast_temp_'),
  'default_acls',(select jsonb_agg(to_jsonb(d) order by d.oid) from pg_default_acl d),
  'roles',(select jsonb_agg(to_jsonb(r) order by r.oid) from pg_roles r),
  'role_memberships',(select jsonb_agg(to_jsonb(m) order by m.roleid,m.member,m.grantor,m.oid) from pg_auth_members m),
  'role_database_settings',(select jsonb_agg(to_jsonb(s) order by s.setdatabase,s.setrole) from pg_db_role_setting s),
  'types',(select jsonb_agg(to_jsonb(t) order by t.oid) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname !~ '^pg_temp_' and n.nspname !~ '^pg_toast_temp_' and t.oid not in (select oid from feature_types)),
  'enums',(select jsonb_agg(to_jsonb(e) order by e.oid) from pg_enum e),
  'rewrites',(select jsonb_agg(to_jsonb(w) order by w.oid) from pg_rewrite w join pg_class c on c.oid=w.ev_class join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_temp_' and n.nspname !~ '^pg_toast_temp_' and c.oid not in (select oid from feature_relations)),
  'columns',(select jsonb_agg(to_jsonb(a) order by a.attrelid,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_temp_' and n.nspname !~ '^pg_toast_temp_' and c.oid not in (select oid from feature_relations)),
  'relations',(select jsonb_agg(case when c.oid in(to_regclass('auth.users'),to_regclass('public.internal_org_people')) then to_jsonb(c)-'relhastriggers' else to_jsonb(c) end order by c.oid) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_temp_' and n.nspname !~ '^pg_toast_temp_' and c.oid not in (select oid from feature_relations)),
  'policies',(select jsonb_agg(to_jsonb(p) order by p.oid) from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_temp_' and n.nspname !~ '^pg_toast_temp_' and c.oid not in (select oid from feature_relations)),
  'constraints',(select jsonb_agg(to_jsonb(k) order by k.oid) from pg_constraint k join pg_namespace n on n.oid=k.connamespace where n.nspname !~ '^pg_temp_' and n.nspname !~ '^pg_toast_temp_' and k.conrelid not in (select oid from feature_relations)),
  'defaults',(select jsonb_agg(to_jsonb(d) order by d.oid) from pg_attrdef d join pg_class c on c.oid=d.adrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_temp_' and n.nspname !~ '^pg_toast_temp_' and c.oid not in (select oid from feature_relations)),
  'routines',(select jsonb_agg(to_jsonb(p) order by p.oid) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname !~ '^pg_temp_' and n.nspname !~ '^pg_toast_temp_'
    and not exists(select 1 from (values ('private','performance_review_word_text_bytes'),('private','performance_review_docx_bytes'),('private','performance_review_actor'),('private','performance_review_identity'),('private','performance_review_candidate'),('private','performance_review_date'),('private','performance_review_lock_people'),('private','performance_review_audience'),('private','performance_review_project'),('public','performance_review_workspace'),('public','start_performance_review'),('private','performance_review_closed'),('private','performance_review_text'),('private','performance_review_nonblank'),('private','performance_review_answers'),('private','performance_review_manager_input'),('private','performance_review_meeting_end'),('private','performance_review_document'),('private','performance_review_meeting_ended'),('public','mutate_performance_review'),('public','get_performance_review_document'),('public','get_performance_review_operation'),('public','claim_performance_review_mail'),('public','begin_performance_review_mail'),('public','finish_performance_review_mail')) f(schema_name,function_name) where f.schema_name=n.nspname and f.function_name=p.proname)),
 'triggers',(select jsonb_agg(to_jsonb(t) order by t.oid) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_temp_' and n.nspname !~ '^pg_toast_temp_' and c.oid not in (select oid from feature_relations) and not exists(select 1 from pg_constraint k where k.oid=t.tgconstraint and k.conrelid in (select oid from feature_relations))),
 'indexes',(select jsonb_agg(to_jsonb(i) order by i.indexrelid) from pg_index i join pg_class c on c.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_temp_' and n.nspname !~ '^pg_toast_temp_' and i.indexrelid not in (select oid from feature_relations)), 'sequences',(select jsonb_agg(to_jsonb(s) order by s.seqrelid) from pg_sequence s where s.seqrelid not in(select oid from feature_relations)));
$performance_security$;
create function pg_temp.performance_release_data() returns jsonb language sql stable set search_path='' as $performance_data$
select jsonb_build_object('tables',(select jsonb_object_agg(n.nspname||'.'||c.relname,(xpath('/table/row/hash/text()',query_to_xml(format('select encode(extensions.digest(coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text collate "C"),''[]'')::text,''sha256''),''hex'') as hash from %I.%I t',n.nspname,c.relname),false,false,'')))[1]::text order by n.nspname,c.relname)
from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private','auth','storage') and c.relkind in('r','p') and c.oid<>to_regclass('private.confirmed_test_purge_schema')),'sequences',(select jsonb_object_agg(n.nspname||'.'||c.relname,(xpath('/table/row/value/text()',query_to_xml(format('select jsonb_build_array(last_value,is_called)::text as value from %I.%I',n.nspname,c.relname),false,false,'')))[1]::text order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private','auth','storage') and c.relkind='S'));
$performance_data$;
create function pg_temp.performance_release_metadata() returns jsonb language sql stable set search_path='' as $performance_metadata$
select jsonb_build_object(
'functions',(select coalesce(jsonb_object_agg(n.nspname||'.'||p.proname||'('||oidvectortypes(p.proargtypes)||')',jsonb_build_object('sha256',encode(extensions.digest(pg_get_functiondef(p.oid),'sha256'),'hex'),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'securityDefiner',p.prosecdef,'config',p.proconfig)),'{}') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where exists(select 1 from(values ('private','performance_review_word_text_bytes'),('private','performance_review_docx_bytes'),('private','performance_review_actor'),('private','performance_review_identity'),('private','performance_review_candidate'),('private','performance_review_date'),('private','performance_review_lock_people'),('private','performance_review_audience'),('private','performance_review_project'),('public','performance_review_workspace'),('public','start_performance_review'),('private','performance_review_closed'),('private','performance_review_text'),('private','performance_review_nonblank'),('private','performance_review_answers'),('private','performance_review_manager_input'),('private','performance_review_meeting_end'),('private','performance_review_document'),('private','performance_review_meeting_ended'),('public','mutate_performance_review'),('public','get_performance_review_document'),('public','get_performance_review_operation'),('public','claim_performance_review_mail'),('public','begin_performance_review_mail'),('public','finish_performance_review_mail')) f(schema_name,function_name) where n.nspname=f.schema_name and p.proname=f.function_name)),
'relations',(select jsonb_object_agg(target,(select jsonb_build_object('owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'forced',c.relforcerowsecurity,'kind',c.relkind,'persistence',c.relpersistence,'options',c.reloptions,'replicaIdentity',c.relreplident,'accessMethod',(select amname from pg_am where oid=c.relam),
'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'acl',a.attacl::text,'identity',a.attidentity::text,'generated',a.attgenerated::text,'storage',a.attstorage::text,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
'constraints',(select jsonb_agg(jsonb_build_object('name',k.conname,'definition',pg_get_constraintdef(k.oid)) order by k.conname) from pg_constraint k where k.conrelid=c.oid),
'indexes',(select jsonb_agg(pg_get_indexdef(i.indexrelid) order by pg_get_indexdef(i.indexrelid)) from pg_index i where i.indrelid=c.oid),
'policies',(select jsonb_agg(to_jsonb(p) order by p.polname) from pg_policy p where p.polrelid=c.oid),
'fkTriggers',(select jsonb_agg(jsonb_build_object('relation',t.tgrelid::regclass::text,'function',t.tgfoid::regprocedure::text,'type',t.tgtype,'enabled',t.tgenabled,'constraint',pg_get_constraintdef(t.tgconstraint),'internal',t.tgisinternal,'deferrable',t.tgdeferrable,'initiallyDeferred',t.tginitdeferred,'arguments',encode(t.tgargs,'hex'),'name',portable.name,'definition',case when portable.name<>t.tgname then overlay(pg_get_triggerdef(t.oid) placing quote_ident(portable.name) from length('CREATE CONSTRAINT TRIGGER ')+1 for length(quote_ident(t.tgname))) else pg_get_triggerdef(t.oid) end,'when',pg_get_expr(t.tgqual,t.tgrelid),'updateColumns',t.tgattr::text,'argumentCount',t.tgnargs,'constraintName',k.conname,'constraintRelation',nullif(t.tgconstrrelid,0)::regclass::text,'constraintIndex',nullif(t.tgconstrindid,0)::regclass::text,'parent',t.tgparentid::text,'oldTable',t.tgoldtable,'newTable',t.tgnewtable) order by t.tgrelid::regclass::text,t.tgfoid::regprocedure::text,k.conname,portable.name) from pg_trigger t left join pg_constraint k on k.oid=t.tgconstraint cross join lateral (select case when t.tgisinternal and k.contype='f' and t.tgname=('RI_ConstraintTrigger_'||case when t.tgrelid=k.conrelid then 'c' else 'a' end||'_'||t.oid::text) then 'RI_ConstraintTrigger_'||case when t.tgrelid=k.conrelid then 'c' else 'a' end||'_<oid>' else t.tgname::text end as name) portable where t.tgrelid=c.oid or t.tgconstraint in (select k.oid from pg_constraint k where k.conrelid=c.oid))) from pg_class c where c.oid=to_regclass(target))) from unnest(array['private.performance_reviews','private.performance_review_events','private.performance_review_operations','private.performance_review_mail_outbox']::text[]) target),
'sequences',(select jsonb_object_agg(target,(select jsonb_build_object('owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'parameters',jsonb_build_object('type',format_type(s.seqtypid,null),'start',s.seqstart::text,'increment',s.seqincrement::text,'min',s.seqmin::text,'max',s.seqmax::text,'cache',s.seqcache::text,'cycle',s.seqcycle)) from pg_class c join pg_sequence s on s.seqrelid=c.oid where c.oid=to_regclass(target))) from unnest(array['private.performance_reviews_review_no_seq','private.performance_review_events_id_seq']::text[]) target));
